public class MainActivity extends AppCompatActivity {
    private static final String API="https://olunaa.vercel.app/api";
    private static final int REQ_MEDIA=701, REQ_NOTIF=702;
    private static final int GREEN=Color.rgb(35,211,108), GREEN2=Color.rgb(18,155,83), BG_D=Color.rgb(7,12,16), SURFACE_D=Color.rgb(13,20,25), CARD_D=Color.rgb(20,29,35), FIELD_D=Color.rgb(28,38,45), TEXT_D=Color.rgb(245,248,249), MUTED_D=Color.rgb(151,165,173);
    private static final int BG_L=Color.rgb(247,249,250), SURFACE_L=Color.WHITE, CARD_L=Color.rgb(242,245,246), FIELD_L=Color.rgb(233,238,240), TEXT_L=Color.rgb(18,27,32), MUTED_L=Color.rgb(91,106,114);
    private final ExecutorService io=Executors.newCachedThreadPool();
    private final Handler main=new Handler(Looper.getMainLooper());
    private android.content.SharedPreferences prefs;
    private LinearLayout root, body;
    private String meId="", meUsername="", meName="", meAvatar="", activeConversation="", activeOtherName="", activeOtherAvatar="";
    private boolean dark=true;
    private int mediaMode=0;
    private Runnable poller;

    private int bg(){return dark?BG_D:BG_L;} private int surface(){return dark?SURFACE_D:SURFACE_L;}
    private int card(){return dark?CARD_D:CARD_L;} private int field(){return dark?FIELD_D:FIELD_L;}
    private int text(){return dark?TEXT_D:TEXT_L;} private int muted(){return dark?MUTED_D:MUTED_L;}
    private GradientDrawable rounded(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;}
    private TextView tv(String s,float z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);return v;}
    private LinearLayout.LayoutParams lp(int h,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,h);p.setMargins(0,0,0,b);return p;}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private void rootBase(){
        root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg());root.setPadding(dp(12),0,dp(12),0);setContentView(root);
        ViewCompat.setOnApplyWindowInsetsListener(root,(v,in)->{android.graphics.Insets x=in.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout());v.setPadding(dp(12)+x.left,x.top,dp(12)+x.right,x.bottom);return in;});
    }
    private EditText input(String hint){EditText e=new EditText(this);e.setHint(hint);e.setHintTextColor(muted());e.setTextColor(text());e.setTextSize(15);e.setSingleLine(true);e.setPadding(dp(18),0,dp(18),0);e.setBackground(rounded(field(),dp(18)));return e;}
    private Button btn(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setTextColor(primary?Color.WHITE:text());b.setTextSize(14);b.setAllCaps(false);b.setMinHeight(0);b.setMinimumHeight(0);b.setPadding(dp(14),0,dp(14),0);b.setBackground(rounded(primary?GREEN2:card(),dp(18)));return b;}
    private ImageView logo(int size){ImageView im=new ImageView(this);im.setImageResource(R.drawable.ic_olunaa);im.setScaleType(ImageView.ScaleType.CENTER_INSIDE);return im;}
    private ImageView avatar(String url,int size){ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.CENTER_CROP);im.setBackground(rounded(field(),100));im.setContentDescription("Profile photo");im.setPadding(2,2,2,2);if(url!=null&&!url.isEmpty())loadImage(im,url);return im;}
    private void loadImage(ImageView im,String url){
        if(url.startsWith("data:image")){try{byte[] r=android.util.Base64.decode(url.substring(url.indexOf(',')+1),android.util.Base64.DEFAULT);Bitmap b=BitmapFactory.decodeByteArray(r,0,r.length);if(b!=null)im.setImageBitmap(b);}catch(Exception ignored){}return;}
        io.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(12000);Bitmap b=BitmapFactory.decodeStream(c.getInputStream());c.disconnect();main.post(()->{if(b!=null)im.setImageBitmap(b);});}catch(Exception ignored){}});
    }
    @Override public void onCreate(Bundle b){
        super.onCreate(b);WindowCompat.enableEdgeToEdge(getWindow());prefs=getSharedPreferences("olunaa_session",MODE_PRIVATE);
        String savedTheme=prefs.getString("theme","dark");dark=savedTheme.equals("system")?((getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES):!savedTheme.equals("light");
        getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE,WindowManager.LayoutParams.FLAG_SECURE);requestNotifications();
        if(prefs.getBoolean("lock",false)&&hasUser())biometric();else if(hasUser()){restoreUser();showHome("Chats");}else showAuth(false);
    }
    private void requestNotifications(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},REQ_NOTIF);}
    private boolean hasUser(){return !prefs.getString("id","").isEmpty()&&!prefs.getString("username","").isEmpty();}
    private void restoreUser(){meId=prefs.getString("id","");meUsername=prefs.getString("username","");meName=prefs.getString("name","");meAvatar=prefs.getString("avatar","");}
    private void saveUser(){prefs.edit().putString("id",meId).putString("username",meUsername).putString("name",meName).putString("avatar",meAvatar).apply();}
    private void setUser(JSONObject u){if(u==null)return;meId=u.optString("id",meId);meUsername=u.optString("username",meUsername);meName=u.optString("displayName",meName);meAvatar=u.optString("avatarUrl",meAvatar);saveUser();}
    private void message(String s){main.post(()->Toast.makeText(this,s,Toast.LENGTH_SHORT).show());}

    private void showAuth(boolean register){
        stopPoll();rootBase();ScrollView scroll=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER_HORIZONTAL);box.setPadding(dp(8),dp(24),dp(8),dp(30));scroll.addView(box);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        box.addView(logo(1),new LinearLayout.LayoutParams(dp(112),dp(112)));TextView brand=tv("OLUNAA",32,text());brand.setTypeface(null,1);brand.setGravity(Gravity.CENTER);box.addView(brand,lp(dp(44),0));TextView tagline=tv(register?"Your identity. Your people. Your space.":"Private conversations, made beautifully.",14,muted());tagline.setGravity(Gravity.CENTER);box.addView(tagline,lp(dp(38),dp(18)));
        LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(18),dp(20),dp(18),dp(20));card.setBackground(rounded(surface(),dp(28)));box.addView(card,lp(-2,dp(14)));TextView title=tv(register?"Create your OLUNAA account":"Welcome back",25,text());title.setTypeface(null,1);card.addView(title,lp(-2,dp(4)));card.addView(tv(register?"Set your name, email and @username.":"Sign in with email or @username.",13,muted()),lp(-2,dp(18)));
        EditText name=null,email=null;if(register){name=input("Display name");email=input("Email address");card.addView(name,lp(dp(54),dp(9)));card.addView(email,lp(dp(54),dp(9)));}
        EditText ident=input(register?"Username":"Email or @username"),pass=input("Password");pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);card.addView(ident,lp(dp(54),dp(9)));card.addView(pass,lp(dp(54),dp(14)));
        Button submit=btn(register?"Create account":"Sign in",true);card.addView(submit,new LinearLayout.LayoutParams(-1,dp(54)));TextView switcher=tv(register?"Already have an account?  Sign in":"New here?  Create an account",14,GREEN);switcher.setGravity(Gravity.CENTER);box.addView(switcher,lp(dp(54),0));
        if(!register){TextView forgot=tv("Forgot password?",13,muted());forgot.setGravity(Gravity.CENTER);box.addView(forgot,lp(dp(38),0));forgot.setOnClickListener(v->showForgot());}
        EditText fName=name,fEmail=email,fIdent=ident,fPass=pass;submit.setOnClickListener(v->{String id=fIdent.getText().toString().trim().replaceFirst("^@","");if(fPass.getText().toString().length()<8||(register&&(fName.getText().toString().trim().isEmpty()||fEmail.getText().toString().trim().isEmpty()||id.isEmpty()))){message("Complete all fields. Password must be 8+ characters.");return;}JSONObject j=new JSONObject();try{j.put("password",fPass.getText().toString());if(register){j.put("displayName",fName.getText().toString().trim());j.put("email",fEmail.getText().toString().trim());j.put("username",id);}else j.put("identifier",id);}catch(Exception ignored){}submit.setEnabled(false);api(register?"/auth/register":"/auth/login","POST",j,r->{submit.setEnabled(true);if(!r.ok){message(r.error);return;}setUser(r.data.optJSONObject("user"));if(register)profilePhotoPrompt();else showHome("Chats");});});switcher.setOnClickListener(v->showAuth(!register));
    }
    private void showForgot(){rootBase();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(12),dp(35),dp(12),0);root.addView(box,new LinearLayout.LayoutParams(-1,-1));TextView back=tv("‹  Sign in",15,GREEN);box.addView(back,lp(-2,dp(18)));back.setOnClickListener(v->showAuth(false));TextView h=tv("Reset password",30,text());h.setTypeface(null,1);box.addView(h,lp(-2,dp(6)));box.addView(tv("We'll send a reset request if the account exists.",14,muted()),lp(-2,dp(20)));EditText id=input("Email or @username");box.addView(id,lp(dp(54),dp(12)));Button go=btn("Send reset request",true);box.addView(go,new LinearLayout.LayoutParams(-1,dp(54)));go.setOnClickListener(v->{JSONObject j=new JSONObject();try{j.put("identifier",id.getText().toString().trim());}catch(Exception ignored){}api("/auth/forgot","POST",j,r->message(r.ok?"Request sent if the account exists.":r.error));});}
    private void profilePhotoPrompt(){new AlertDialog.Builder(this).setTitle("Make your profile yours").setMessage("Add a clear profile photo. You can skip now and add one later in Profile.").setPositiveButton("Choose photo",(d,w)->{mediaMode=1;pickImage();}).setNegativeButton("Skip",(d,w)->showHome("Chats")).setCancelable(false).show();}

    private void showHome(String tab){
        stopPoll();rootBase();LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(0,dp(6),0,dp(5));top.addView(logo(1),new LinearLayout.LayoutParams(dp(44),dp(50)));LinearLayout titleBox=new LinearLayout(this);titleBox.setOrientation(LinearLayout.VERTICAL);titleBox.setPadding(dp(8),0,0,0);TextView title=tv(tab.equals("Chats")?"OLUNAA":tab,23,text());title.setTypeface(null,1);TextView sub=tv("@"+meUsername,12,muted());titleBox.addView(title);titleBox.addView(sub);top.addView(titleBox,new LinearLayout.LayoutParams(0,dp(58),1));TextView search=tv("⌕",28,text());TextView menu=tv("⋮",28,text());search.setGravity(Gravity.CENTER);menu.setGravity(Gravity.CENTER);top.addView(search,new LinearLayout.LayoutParams(dp(48),dp(50)));top.addView(menu,new LinearLayout.LayoutParams(dp(42),dp(50)));root.addView(top);
        body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setBackground(rounded(surface(),dp(24)));nav.setPadding(0,dp(3),0,dp(3));String[] labels={"Chats","Updates","Communities","Calls","Profile"};String[] glyphs={"◉","◌","▣","☎","●"};for(int i=0;i<labels.length;i++){final String n=labels[i];LinearLayout item=new LinearLayout(this);item.setOrientation(LinearLayout.VERTICAL);item.setGravity(Gravity.CENTER);TextView g=tv(glyphs[i],20,n.equals(tab)?GREEN:muted());g.setGravity(Gravity.CENTER);TextView t=tv(n,10,n.equals(tab)?text():muted());t.setGravity(Gravity.CENTER);item.addView(g,new LinearLayout.LayoutParams(-1,dp(27)));item.addView(t,new LinearLayout.LayoutParams(-1,dp(21)));item.setOnClickListener(v->showHome(n));nav.addView(item,new LinearLayout.LayoutParams(0,dp(58),1));}root.addView(nav,lp(dp(64),0));search.setOnClickListener(v->showSearch());menu.setOnClickListener(v->showMenu());
        if(tab.equals("Chats"))loadChats();else if(tab.equals("Updates"))loadStatus();else if(tab.equals("Communities"))loadChannels();else if(tab.equals("Calls"))loadCalls();else loadProfile();
    }
    private void heading(String h,String s){TextView a=tv(h,24,text());a.setTypeface(null,1);body.addView(a,lp(-2,dp(3)));body.addView(tv(s,13,muted()),lp(-2,dp(14)));}
    private void cardRow(LinearLayout row){row.setPadding(dp(12),dp(10),dp(12),dp(10));row.setBackground(rounded(card(),dp(20)));body.addView(row,lp(dp(78),dp(7)));}
    private void loadChats(){heading("Messages","Your private conversations");Button newChat=btn("＋  New chat",true);body.addView(newChat,lp(dp(50),dp(12)));newChat.setOnClickListener(v->showSearch());api("/conversations","GET",null,r->{if(!r.ok){message(r.error);return;}JSONArray a=r.data.optJSONArray("conversations");if(a==null||a.length()==0){empty("No conversations yet","Search for an @username to start your first chat.");return;}for(int i=0;i<a.length();i++){JSONObject c=a.optJSONObject(i),o=c==null?null:c.optJSONObject("other");if(o!=null)chatRow(c,o);}});}
    private void chatRow(JSONObject c,JSONObject o){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);ImageView av=avatar(o.optString("avatarUrl",""),1);row.addView(av,new LinearLayout.LayoutParams(dp(54),dp(54)));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(12),0,dp(4),0);TextView n=tv(o.optString("displayName","User")+(o.optBoolean("verified")?"  ✓":""),16,text());n.setTypeface(null,1);TextView u=tv("@"+o.optString("username",""),12,muted());JSONObject lm=c.optJSONObject("lastMessage");TextView last=tv(lm==null?"Start a conversation":lm.optString("body","").isEmpty()?"Photo":lm.optString("body"),12,muted());info.addView(n);info.addView(u);info.addView(last);row.addView(info,new LinearLayout.LayoutParams(0,-1,1));cardRow(row);row.setOnClickListener(v->openChat(c.optString("id"),o.optString("displayName","User"),o.optString("avatarUrl","")));}
    private void showSearch(){rootBase();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(0,dp(8),0,0);root.addView(box,new LinearLayout.LayoutParams(-1,-1));LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView back=tv("‹",34,text());back.setGravity(Gravity.CENTER);bar.addView(back,new LinearLayout.LayoutParams(dp(48),dp(54)));EditText q=input("Search @username or name");bar.addView(q,new LinearLayout.LayoutParams(0,dp(54),1));box.addView(bar,lp(dp(62),dp(5)));back.setOnClickListener(v->showHome("Chats"));LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);ScrollView sc=new ScrollView(this);sc.addView(results);box.addView(sc,new LinearLayout.LayoutParams(-1,0,1));q.setOnEditorActionListener((v,a,e)->{searchUsers(q.getText().toString(),results);return true;});q.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(q,InputMethodManager.SHOW_IMPLICIT);}
    private void searchUsers(String q,LinearLayout results){results.removeAllViews();if(q.trim().isEmpty())return;api("/search?q="+URLEncoder.encode(q.trim(),StandardCharsets.UTF_8),"GET",null,r->{if(!r.ok){message(r.error);return;}JSONArray users=r.data.optJSONArray("users");if(users==null||users.length()==0){TextView x=tv("No people found.",15,muted());x.setPadding(dp(16),dp(25),dp(16),0);results.addView(x);return;}for(int i=0;i<users.length();i++){JSONObject u=users.optJSONObject(i);if(u!=null)searchRow(results,u);}});}
    private void searchRow(LinearLayout results,JSONObject u){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(10),dp(12),dp(10));row.setBackground(rounded(card(),dp(20)));ImageView av=avatar(u.optString("avatarUrl",""),1);row.addView(av,new LinearLayout.LayoutParams(dp(52),dp(52)));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(12),0,0,0);TextView n=tv(u.optString("displayName","User"),16,text());n.setTypeface(null,1);info.addView(n);info.addView(tv("@"+u.optString("username",""),12,muted()));info.addView(tv(u.optBoolean("online")?"Online":"Offline",11,u.optBoolean("online")?GREEN:muted()));row.addView(info,new LinearLayout.LayoutParams(0,dp(70),1));results.addView(row,lp(dp(72),dp(7)));row.setOnClickListener(v->createConversation(u));}
    private void createConversation(JSONObject u){JSONObject j=new JSONObject();try{j.put("userId",u.optString("id"));}catch(Exception ignored){}api("/conversations","POST",j,r->{if(!r.ok){message(r.error);return;}openChat(r.data.optString("conversationId"),u.optString("displayName","User"),u.optString("avatarUrl",""));});}

    private void openChat(String id,String name,String av){
        activeConversation=id;activeOtherName=name;activeOtherAvatar=av;stopPoll();rootBase();LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(0,dp(5),0,dp(5));TextView back=tv("‹",34,text());back.setGravity(Gravity.CENTER);top.addView(back,new LinearLayout.LayoutParams(dp(45),dp(54)));ImageView img=avatar(av,1);top.addView(img,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout title=new LinearLayout(this);title.setOrientation(LinearLayout.VERTICAL);title.setPadding(dp(10),0,0,0);TextView n=tv(name,17,text());n.setTypeface(null,1);title.addView(n);title.addView(tv("OLUNAA chat",11,muted()));top.addView(title,new LinearLayout.LayoutParams(0,dp(54),1));TextView voice=tv("☎",21,text()),video=tv("▣",20,text());voice.setGravity(Gravity.CENTER);video.setGravity(Gravity.CENTER);top.addView(voice,new LinearLayout.LayoutParams(dp(44),dp(54)));top.addView(video,new LinearLayout.LayoutParams(dp(44),dp(54)));root.addView(top);
        ScrollView sc=new ScrollView(this);LinearLayout messages=new LinearLayout(this);messages.setOrientation(LinearLayout.VERTICAL);messages.setPadding(dp(4),dp(10),dp(4),dp(10));sc.addView(messages);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout composer=new LinearLayout(this);composer.setGravity(Gravity.CENTER_VERTICAL);composer.setPadding(0,dp(6),0,dp(5));TextView attach=tv("＋",27,text());attach.setGravity(Gravity.CENTER);composer.addView(attach,new LinearLayout.LayoutParams(dp(46),dp(52)));EditText textBox=input("Message");composer.addView(textBox,new LinearLayout.LayoutParams(0,dp(52),1));TextView send=tv("➤",25,GREEN);send.setGravity(Gravity.CENTER);composer.addView(send,new LinearLayout.LayoutParams(dp(52),dp(52)));root.addView(composer);
        back.setOnClickListener(v->showHome("Chats"));attach.setOnClickListener(v->{mediaMode=3;pickImage();});send.setOnClickListener(v->sendMessage(textBox,messages));voice.setOnClickListener(v->callNotice(false));video.setOnClickListener(v->callNotice(true));loadMessages(messages);poller=()->{loadMessages(messages);main.postDelayed(poller,2500);};main.postDelayed(poller,2500);
    }
    private void loadMessages(LinearLayout list){api("/messages?conversationId="+URLEncoder.encode(activeConversation,StandardCharsets.UTF_8),"GET",null,r->{if(!r.ok)return;JSONArray a=r.data.optJSONArray("messages");if(a==null)return;list.removeAllViews();for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m!=null)bubble(list,m);}list.postDelayed(()->{ScrollView parent=findScroll(list);if(parent!=null)parent.fullScroll(View.FOCUS_DOWN);},80);});}
    private ScrollView findScroll(View v){View p=v;while(p.getParent() instanceof View){p=(View)p.getParent();if(p instanceof ScrollView)return (ScrollView)p;}return null;}
    private void bubble(LinearLayout list,JSONObject m){boolean mine=meId.equals(m.optString("senderId"));LinearLayout wrap=new LinearLayout(this);wrap.setOrientation(LinearLayout.VERTICAL);wrap.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);String media=m.optString("mediaUrl","");if(!media.isEmpty()){ImageView photo=new ImageView(this);photo.setScaleType(ImageView.ScaleType.CENTER_CROP);photo.setBackground(rounded(card(),dp(18)));loadImage(photo,media);wrap.addView(photo,new LinearLayout.LayoutParams(dp(250),dp(210)));}String bodyText=m.optString("body","");if(!bodyText.isEmpty()){TextView b=tv(bodyText,15,text());b.setPadding(dp(15),dp(10),dp(15),dp(10));b.setMaxWidth(dp(310));b.setBackground(rounded(mine?GREEN2:card(),dp(18)));wrap.addView(b,lp(-2,0));}list.addView(wrap,lp(-2,dp(6)));}
    private void sendMessage(EditText box,LinearLayout list){String s=box.getText().toString().trim();if(s.isEmpty())return;JSONObject j=new JSONObject();try{j.put("conversationId",activeConversation);j.put("body",s);}catch(Exception ignored){}box.setText("");api("/messages","POST",j,r->{if(!r.ok)message(r.error);else loadMessages(list);});}
    private void callNotice(boolean video){new AlertDialog.Builder(this).setTitle(video?"Video call":"Voice call").setMessage("The call screen is ready, but live audio/video signaling is not yet exposed by the OLUNAA server.").setPositiveButton("OK",null).show();}

    private void loadStatus(){heading("Updates","Stories disappear automatically after their expiry.");Button add=btn("＋  Add status",true);body.addView(add,lp(dp(50),dp(12)));add.setOnClickListener(v->{mediaMode=2;pickImage();});api("/status","GET",null,r->{if(!r.ok){message(r.error);return;}JSONArray a=r.data.optJSONArray("stories");if(a==null||a.length()==0){empty("No updates yet","Post your first photo status.");return;}for(int i=0;i<a.length();i++){JSONObject s=a.optJSONObject(i);if(s!=null)statusRow(s);}});}
    private void statusRow(JSONObject s){JSONObject u=s.optJSONObject("user");LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);ImageView av=avatar(u==null?"":u.optString("avatarUrl",""),1);row.addView(av,new LinearLayout.LayoutParams(dp(58),dp(58)));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(12),0,0,0);info.addView(tv(u==null?"Unknown":u.optString("displayName","User"),16,text()));info.addView(tv(u==null?"":("@"+u.optString("username","")),12,muted()));info.addView(tv(s.optString("caption","").isEmpty()?"Photo update":s.optString("caption"),12,muted()));row.addView(info,new LinearLayout.LayoutParams(0,dp(70),1));body.addView(row,lp(dp(76),dp(7)));row.setOnClickListener(v->viewStatus(s));}
    private void viewStatus(JSONObject s){JSONObject j=new JSONObject();try{j.put("storyId",s.optString("id"));}catch(Exception ignored){}api("/status","PUT",j,r->{});JSONArray views=s.optJSONArray("views");new AlertDialog.Builder(this).setTitle(s.optString("caption","Status")).setMessage("Views: "+(views==null?0:views.length())).setPositiveButton("Close",null).show();}

    private void loadChannels(){heading("Communities","Public channels and announcements.");api("/channels","GET",null,r->{if(!r.ok){message(r.error);return;}JSONArray a=r.data.optJSONArray("channels");if(a==null||a.length()==0){empty("No communities yet","Public communities will appear here.");return;}for(int i=0;i<a.length();i++){JSONObject c=a.optJSONObject(i);if(c!=null)channelRow(c);}});}
    private void channelRow(JSONObject c){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);ImageView av=avatar(c.optString("avatarUrl",""),1);row.addView(av,new LinearLayout.LayoutParams(dp(54),dp(54)));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(12),0,0,0);TextView n=tv(c.optString("name","Community")+(c.optBoolean("verified")?"  ✓":""),16,text());n.setTypeface(null,1);info.addView(n);info.addView(tv("@"+c.optString("handle",""),12,muted()));info.addView(tv(c.optString("description","Public channel"),12,muted()));row.addView(info,new LinearLayout.LayoutParams(0,dp(70),1));body.addView(row,lp(dp(76),dp(7)));row.setOnClickListener(v->openChannel(c.optString("handle","")));}
    private void openChannel(String h){api("/channels?handle="+URLEncoder.encode(h,StandardCharsets.UTF_8),"GET",null,r->{if(!r.ok){message(r.error);return;}JSONObject c=r.data.optJSONObject("channel");if(c==null)return;StringBuilder feed=new StringBuilder(c.optString("description","")).append("\n\n");JSONArray msgs=c.optJSONArray("messages");if(msgs!=null)for(int i=0;i<Math.min(msgs.length(),10);i++){JSONObject m=msgs.optJSONObject(i);if(m!=null)feed.append(m.optString("body","")).append("\n\n");}new AlertDialog.Builder(this).setTitle(c.optString("name","Community")).setMessage(feed.toString()).setPositiveButton("Close",null).show();});}

    private void loadCalls(){heading("Calls","Your call center.");LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(18),dp(18),dp(18),dp(18));box.setBackground(rounded(card(),dp(22)));box.addView(tv("☎",44,GREEN),lp(-2,dp(6)));TextView h=tv("Calls are ready in the app shell",20,text());h.setTypeface(null,1);box.addView(h);box.addView(tv("Voice/video controls are connected to chats. Live signaling requires a call backend.",13,muted()));body.addView(box,lp(-2,dp(12)));Button b=btn("Call settings",false);body.addView(b,new LinearLayout.LayoutParams(-1,dp(50)));b.setOnClickListener(v->showSettings());}

    private void loadProfile(){heading("Profile","Your OLUNAA identity");LinearLayout hero=new LinearLayout(this);hero.setGravity(Gravity.CENTER_VERTICAL);hero.setPadding(dp(16),dp(16),dp(16),dp(16));hero.setBackground(rounded(card(),dp(24)));ImageView av=avatar(meAvatar,1);hero.addView(av,new LinearLayout.LayoutParams(dp(82),dp(82)));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(15),0,0,0);TextView n=tv(meName,22,text());n.setTypeface(null,1);info.addView(n);info.addView(tv("@"+meUsername,13,GREEN));info.addView(tv("OLUNAA member",12,muted()));hero.addView(info,new LinearLayout.LayoutParams(0,dp(100),1));body.addView(hero,lp(-2,dp(12)));Button edit=btn("Edit profile",true);body.addView(edit,lp(dp(50),dp(8)));edit.setOnClickListener(v->editProfile());Button settings=btn("Settings & privacy",false);body.addView(settings,lp(dp(50),dp(8)));settings.setOnClickListener(v->showSettings());Button lock=btn(prefs.getBoolean("lock",false)?"Disable app lock":"Enable fingerprint / device lock",false);body.addView(lock,lp(dp(50),dp(8)));lock.setOnClickListener(v->{prefs.edit().putBoolean("lock",!prefs.getBoolean("lock",false)).apply();loadProfile();});Button logout=btn("Sign out",false);body.addView(logout,lp(dp(50),0));logout.setOnClickListener(v->logout());}
    private void editProfile(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(5),0,dp(5),0);EditText name=input("Display name");name.setText(meName);EditText user=input("Username");user.setText("@"+meUsername);EditText bio=input("Bio");box.addView(name,lp(dp(52),dp(8)));box.addView(user,lp(dp(52),dp(8)));box.addView(bio,lp(dp(52),0));new AlertDialog.Builder(this).setTitle("Edit profile").setView(box).setPositiveButton("Save",(d,w)->{JSONObject j=new JSONObject();try{j.put("displayName",name.getText().toString().trim());j.put("username",user.getText().toString().trim());j.put("bio",bio.getText().toString().trim());}catch(Exception ignored){}api("/profile","PATCH",j,r->{if(!r.ok){message(r.error);return;}setUser(r.data.optJSONObject("user"));showHome("Profile");});}).setNegativeButton("Cancel",null).show();}
    private void showSettings(){
        rootBase();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(0,dp(10),0,dp(15));root.addView(box,new LinearLayout.LayoutParams(-1,-1));LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);TextView back=tv("‹",34,text());back.setGravity(Gravity.CENTER);head.addView(back,new LinearLayout.LayoutParams(dp(48),dp(55)));TextView h=tv("Settings",25,text());h.setTypeface(null,1);head.addView(h);box.addView(head,lp(dp(62),dp(10)));back.setOnClickListener(v->showHome("Profile"));
        box.addView(settingTitle("Appearance"));addThemeRow(box,"Dark mode","Deep OLED-friendly theme",0);addThemeRow(box,"Light mode","Bright clean theme",1);addThemeRow(box,"System default","Follow Android appearance",2);
        box.addView(settingTitle("Privacy & security"));addActionRow(box,"Fingerprint / device lock","Protect OLUNAA when opening",()->{prefs.edit().putBoolean("lock",!prefs.getBoolean("lock",false)).apply();message(prefs.getBoolean("lock",false)?"App lock enabled":"App lock disabled");});addActionRow(box,"Notifications","Android notification permission",this::requestNotifications);addActionRow(box,"Sign out","Clear local session on this device",this::logout);
        box.addView(settingTitle("About"));box.addView(tv("OLUNAA • Native Android\nStandalone mobile client\nSmooth UI • secure session • image chat • status • communities",14,muted()),lp(-2,dp(20)));
    }
    private TextView settingTitle(String s){TextView t=tv(s,12,GREEN);t.setTypeface(null,1);t.setPadding(dp(10),dp(18),0,dp(8));return t;}
    private void addThemeRow(LinearLayout box,String title,String sub,int mode){String current=prefs.getString("theme","dark");LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(14),dp(10),dp(14),dp(10));row.setBackground(rounded(card(),dp(18)));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.addView(tv(title,16,text()));info.addView(tv(sub,12,muted()));row.addView(info,new LinearLayout.LayoutParams(0,dp(62),1));RadioButton radio=new RadioButton(this);radio.setChecked((mode==0&&current.equals("dark"))||(mode==1&&current.equals("light"))||(mode==2&&current.equals("system")));row.addView(radio);box.addView(row,lp(dp(70),dp(6)));row.setOnClickListener(v->{if(mode==0){prefs.edit().putString("theme","dark").apply();dark=true;}else if(mode==1){prefs.edit().putString("theme","light").apply();dark=false;}else{prefs.edit().putString("theme","system").apply();dark=(getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES;}showSettings();});}
    private void addActionRow(LinearLayout box,String title,String sub,Runnable action){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(14),dp(10),dp(14),dp(10));row.setBackground(rounded(card(),dp(18)));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.addView(tv(title,16,text()));info.addView(tv(sub,12,muted()));row.addView(info,new LinearLayout.LayoutParams(0,dp(62),1));TextView arrow=tv("›",26,muted());arrow.setGravity(Gravity.CENTER);row.addView(arrow,new LinearLayout.LayoutParams(dp(35),dp(62)));box.addView(row,lp(dp(70),dp(6)));row.setOnClickListener(v->action.run());}
    private void showMenu(){String[] items={"Profile","Settings","Toggle dark/light","Sign out"};new AlertDialog.Builder(this).setTitle("OLUNAA").setItems(items,(d,w)->{if(w==0)showHome("Profile");else if(w==1)showSettings();else if(w==2){dark=!dark;prefs.edit().putString("theme",dark?"dark":"light").apply();showHome("Chats");}else logout();}).show();}
    private void empty(String h,String s){LinearLayout e=new LinearLayout(this);e.setOrientation(LinearLayout.VERTICAL);e.setGravity(Gravity.CENTER);e.setPadding(dp(25),dp(45),dp(25),dp(45));TextView i=tv("◉",50,GREEN);i.setGravity(Gravity.CENTER);e.addView(i,new LinearLayout.LayoutParams(-1,dp(65)));TextView a=tv(h,20,text());a.setTypeface(null,1);a.setGravity(Gravity.CENTER);e.addView(a);TextView b=tv(s,13,muted());b.setGravity(Gravity.CENTER);b.setPadding(0,dp(8),0,0);e.addView(b);body.addView(e);}

    private void pickImage(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,REQ_MEDIA);}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode!=REQ_MEDIA||resultCode!=RESULT_OK||data==null||data.getData()==null)return;Uri u=data.getData();io.execute(()->{String dataUrl=toDataUrl(u);main.post(()->{if(dataUrl==null){message("Could not read image.");return;}if(mediaMode==1){JSONObject j=new JSONObject();try{j.put("avatarUrl",dataUrl);}catch(Exception ignored){}api("/profile","PATCH",j,r->{if(r.ok){setUser(r.data.optJSONObject("user"));showHome("Profile");}else message(r.error);});}else if(mediaMode==2)postStatus(dataUrl);else if(mediaMode==3)sendMedia(dataUrl);});});}
    private String toDataUrl(Uri uri){try{Bitmap b=BitmapFactory.decodeStream(getContentResolver().openInputStream(uri));if(b==null)return null;int max=1280;float scale=Math.min(1f,Math.min((float)max/b.getWidth(),(float)max/b.getHeight()));if(scale<1f)b=Bitmap.createScaledBitmap(b,Math.max(1,(int)(b.getWidth()*scale)),Math.max(1,(int)(b.getHeight()*scale)),true);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.JPEG,82,out);return "data:image/jpeg;base64,"+android.util.Base64.encodeToString(out.toByteArray(),android.util.Base64.NO_WRAP);}catch(Exception e){return null;}}
    private void postStatus(String media){EditText cap=input("Caption (optional)");new AlertDialog.Builder(this).setTitle("New status").setView(cap).setPositiveButton("Post",(d,w)->{JSONObject j=new JSONObject();try{j.put("mediaUrl",media);j.put("caption",cap.getText().toString().trim());}catch(Exception ignored){}api("/status","POST",j,r->{if(!r.ok)message(r.error);else showHome("Updates");});}).setNegativeButton("Cancel",null).show();}
    private void sendMedia(String media){JSONObject j=new JSONObject();try{j.put("conversationId",activeConversation);j.put("body","");j.put("mediaUrl",media);j.put("mediaType","image");}catch(Exception ignored){}api("/messages","POST",j,r->{if(!r.ok)message(r.error);else message("Photo sent.");});}
    private void logout(){stopPoll();api("/auth/logout","POST",new JSONObject(),r->{prefs.edit().clear().apply();meId=meUsername=meName=meAvatar="";showAuth(false);});}
    private void biometric(){BiometricManager bm=BiometricManager.from(this);if(bm.canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_STRONG|BiometricManager.Authenticators.DEVICE_CREDENTIAL)==BiometricManager.BIOMETRIC_SUCCESS){BiometricPrompt p=new BiometricPrompt(this,ContextCompat.getMainExecutor(this),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){restoreUser();showHome("Chats");}@Override public void onAuthenticationFailed(){message("Authentication failed.");}});p.authenticate(new BiometricPrompt.PromptInfo.Builder().setTitle("Unlock OLUNAA").setSubtitle("Use fingerprint or device credentials").setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG|BiometricManager.Authenticators.DEVICE_CREDENTIAL).build());}else{restoreUser();showHome("Chats");}}
    private void stopPoll(){if(poller!=null){main.removeCallbacks(poller);poller=null;}}
    private static class Result{boolean ok;String error;JSONObject data;Result(boolean o,String e,JSONObject d){ok=o;error=e;data=d;}}
    private interface Callback{void done(Result r);}
    private void api(String path,String method,JSONObject body,Callback cb){io.execute(()->{Result res;try{HttpURLConnection c=(HttpURLConnection)new URL(API+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setDoInput(true);c.setRequestProperty("Accept","application/json");String cookies=prefs.getString("cookies","");if(!cookies.isEmpty())c.setRequestProperty("Cookie",cookies);if(body!=null&&!method.equals("GET")){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();String set=c.getHeaderField("Set-Cookie");if(set!=null)saveCookie(set);InputStream in=code>=400?c.getErrorStream():c.getInputStream();String raw=read(in);c.disconnect();JSONObject data=raw.isEmpty()?new JSONObject():new JSONObject(raw);res=new Result(code>=200&&code<300,data.optString("error","Request failed ("+code+")"),data);}catch(Exception e){res=new Result(false,"Connection error. Check your internet and try again.",new JSONObject());}Result rr=res;main.post(()->cb.done(rr));});}
    private String read(InputStream in)throws Exception{if(in==null)return "";BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();String x;while((x=r.readLine())!=null)s.append(x);r.close();return s.toString();}
    private void saveCookie(String set){String cookie=set.split(";",2)[0];String old=prefs.getString("cookies","");Map<String,String> m=new LinkedHashMap<>();for(String x:old.split(";")){if(x.trim().isEmpty()||!x.contains("="))continue;String[] p=x.split("=",2);m.put(p[0].trim(),p[1]);}if(cookie.contains("=")){String[] p=cookie.split("=",2);m.put(p[0].trim(),p[1]);}StringBuilder out=new StringBuilder();for(Map.Entry<String,String> e:m.entrySet()){if(out.length()>0)out.append("; ");out.append(e.getKey()).append("=").append(e.getValue());}prefs.edit().putString("cookies",out.toString()).apply();}
}
